class FlightBoardCardEditor extends HTMLElement {
  setConfig(config) { this._config = Object.assign({}, config || {}); this._render(); }
  set hass(hass) { this._hass = hass; if (this._form) this._form.hass = hass; else this._render(); }
  async _ensureForm() {
    if (customElements.get("ha-form")) return;
    try {
      const helpers = await window.loadCardHelpers();
      const c = await helpers.createCardElement({ type: "entities", entities: [] });
      if (c && c.constructor && c.constructor.getConfigElement) await c.constructor.getConfigElement();
    } catch (e) {}
  }
  async _render() {
    if (!this._config || !this._hass) return;
    if (!this._form) {
      await this._ensureForm();
      if (this._form) return;
      this._form = document.createElement("ha-form");
      this._form.computeLabel = (s) => FBC_LABELS[s.name] || s.title || s.name;
      this._form.addEventListener("value-changed", (ev) => {
        const v = Object.assign({}, ev.detail.value);
        for (const k of Object.keys(v)) if (v[k] === FBC_DEFAULTS[k] || v[k] === "" || v[k] === undefined) delete v[k];
        v.type = this._config.type || "custom:flight-board-card";
        this._config = v;
        this.dispatchEvent(new CustomEvent("config-changed", { detail: { config: v }, bubbles: true, composed: true }));
      });
      this.appendChild(this._form);
    }
    const data = Object.assign({}, FBC_DEFAULTS, this._config);
    data.theme = fbcTheme(data.theme) || "classic";
    this._form.hass = this._hass;
    this._form.data = data;
    this._form.schema = FBC_SCHEMA;
  }
}

if (!customElements.get("flight-board-card-editor")) customElements.define("flight-board-card-editor", FlightBoardCardEditor);
if (!customElements.get("flight-board-card")) {
  customElements.define("flight-board-card", FlightBoardCard);
  window.customCards = window.customCards || [];
  window.customCards.push({ type: "flight-board-card", name: "Flight Board Card", description: "Airport departures and arrivals board with classic board styles (Flightradar24)", preview: false, documentationURL: "https://github.com/stargazer992/flight-board-card" });
  console.info("%c FLIGHT-BOARD-CARD %c " + FBC_VERSION, "background:#ffd21f;color:#111;font-weight:700", "");
}
